<section class="container page-section"><p class="breadcrumb"><a href="/">หน้าแรก</a> / <a href="<?= $item['type']==='post'?'/news':($item['type']==='event'?'/events':'/media') ?>"><?= e(CONTENT_TYPES[$item['type']]) ?></a> / รายละเอียด</p><article class="article"><div class="article-heading"><span class="badge"><?= e($item['category_name'] ?? CONTENT_TYPES[$item['type']]) ?></span><h1><?= e($item['title']) ?></h1><p class="lead"><?= e($item['excerpt']) ?></p><div class="article-meta"><span><?= icon('calendar',16) ?> <?= e(thai_date($item['published_at'])) ?></span><?php if($item['updated_at']>$item['published_at']): ?><span>ปรับปรุง <?= e(thai_date($item['updated_at'])) ?></span><?php endif ?><button class="share-button" data-copy type="button"><?= icon('news',17) ?> คัดลอกลิงก์</button></div></div>
<?php if($item['type']==='event'): ?><div class="event-info"><h2>ข้อมูลกิจกรรม</h2><?php if($item['event_status']==='cancelled'): ?><p class="alert error">กิจกรรมนี้ถูกยกเลิก</p><?php endif ?><p><?= icon('calendar') ?> <?= e(thai_date($item['starts_at'])) ?><?php if($item['starts_at']): ?> · <?= e(date('H:i',strtotime($item['starts_at']))) ?> น. (เวลาไทย)<?php endif ?></p><?php if($item['ends_at'] && $item['ends_at']!==$item['starts_at']): ?><p>ถึง <?= e(thai_date($item['ends_at'])) ?> <?= e(date('H:i',strtotime($item['ends_at']))) ?> น.</p><?php endif ?><p><?= icon('pin') ?> <?= e($item['location']?:'สถานที่รอประกาศ') ?></p><?php if($item['event_status']!=='cancelled' && safe_url($item['external_url']) && (!$item['ends_at']||$item['ends_at']>=now())): ?><a class="button" href="<?= e($item['external_url']) ?>" target="_blank" rel="noopener noreferrer">ข้อมูล / ลงทะเบียนเว็บไซต์ภายนอก ↗</a><?php endif ?></div><?php endif ?>
<?php if($item['type']!=='album'): ?><img class="article-cover" src="<?= e(image_url($item['cover_id']?(int)$item['cover_id']:null)) ?>" alt="<?= e($item['title']) ?>"><?php endif ?><div class="article-body"><?= formatted_body($item['body']) ?></div>
<?php $photos=array_filter($files,fn($f)=>str_starts_with($f['mime'],'image/')); $docs=array_filter($files,fn($f)=>!str_starts_with($f['mime'],'image/')); if($photos): ?><div class="album-grid"><?php foreach($photos as $file): ?><div class="gallery-item"><button class="gallery-photo" type="button" data-gallery="<?= e(image_url((int)$file['id'])) ?>" data-caption="<?= e($file['alt']?:$file['name']) ?>"><img src="<?= e(image_url((int)$file['id'])) ?>" alt="<?= e($file['alt']?:$file['name']) ?>" loading="lazy"><span><?= icon('search',19) ?></span></button><a class="button secondary small gallery-download" href="/files/<?= (int)$file['id'] ?>?download=1" aria-label="ดาวน์โหลดรูป <?= e($file['alt']?:$file['name']) ?>"><?= icon('download',18) ?> ดาวน์โหลดรูป</a></div><?php endforeach ?></div><?php elseif($item['type']==='album'): $emptyTitle='ยังไม่มีภาพในอัลบั้ม'; require ROOT . '/views/partials/empty.php'; endif ?>
<?php if($docs): ?><section class="attachments"><h2>เอกสารประกอบ</h2><?php foreach($docs as $file): ?><div class="file-row"><?= icon('news',27) ?><span><strong><?= e($file['name']) ?></strong><small><?= e(strtoupper(pathinfo($file['path'],PATHINFO_EXTENSION))) ?> · <?= number_format($file['size']/1024,0) ?> KB</small></span><a class="button secondary" href="/files/<?= $file['id'] ?>?download=1"><?= icon('download',18) ?> ดาวน์โหลด</a></div><?php endforeach ?></section><?php endif ?>
<a class="text-link" href="<?= $item['type']==='post'?'/news':($item['type']==='event'?'/events':'/media') ?>" data-back>← กลับรายการ</a></article><?php if($related && $item['type']==='post'): ?><section class="section"><div class="section-heading"><h2>ข่าวที่เกี่ยวข้อง</h2></div><div class="news-grid"><?php foreach($related as $card) require ROOT . '/views/partials/card.php' ?></div></section><?php endif ?></section>
